SELECT m."league_id", l."id" AS lid, l."name", COUNT(*) AS n, MIN(m."season"), MAX(m."season")
FROM "match" m LEFT JOIN "league" l ON l."id" = m."league_id"
GROUP BY m."league_id", l."id", l."name";

