WITH anemic AS (
  SELECT DISTINCT p."id", p."sex" FROM "patient" p JOIN "laboratory" l ON l."id" = p."id" WHERE l."hgb" < 10
), rnp_max AS (
  SELECT l."id", MAX(l."rnp"::numeric) AS mx FROM "laboratory" l WHERE l."rnp" ~ '^\s*[0-9]+(\.[0-9]+)?\s*$' GROUP BY l."id"
), top AS (SELECT MAX(r.mx) AS m FROM rnp_max r JOIN anemic a ON a."id" = r."id")
SELECT a."id", a."sex", r.mx AS rnp_max FROM anemic a JOIN rnp_max r ON r."id" = a."id", top WHERE r.mx = top.m

